@startuml

class InsuranceCompany {}

class Policy {
  + policyType : string
}

class CarLiabilityPolicy {
  + coverageLimit : double
}

class LifePolicy {
  + beneficiaryName : string
}

class RiskPolicy {
  + riskDescription : string
}

class Customer {
  + name : string
  + customerId : int
}

class Contract {
  + contractId : int
  + startDate : date
  + endDate : date
}

InsuranceCompany "1" -- "0..*" Policy
InsuranceCompany "1" -- "0..*" Customer
Customer "1" -- "0..*" Contract
Policy "1" -- "0..*" Contract

CarLiabilityPolicy --|> Policy
LifePolicy --|> Policy
RiskPolicy --|> Policy

@enduml

